let introT=0;
const smt=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x)};
function introStep(dt){
  introT+=dt;const T=introT,RUN=1.1,END=2.4;
  body.rotation.x-=body.rotation.x*Math.min(1,dt*12);
  if(T<RUN)body.rotation.x=-0.95*Math.pow(Math.abs(Math.sin(T*8)),2);
  seeds.visible=T<RUN;
  if(T<RUN){legL.rotation.x=legR.rotation.x=0;body.position.y=0}
  else{const f=t*22;legL.rotation.x=Math.sin(f)*0.9;legR.rotation.x=-Math.sin(f)*0.9;body.position.y=Math.abs(Math.sin(f))*0.12}
  const sI=T>=RUN?13*smt((T-RUN)/0.8):0,dz=sI*dt;speed=sI;
  animDeco(dt,sI,true);for(let i=deco.length-1;i>=0;i--){const d=deco[i];if(d.z>12){scene.remove(d.g);deco.splice(i,1)}}
  const k=smt((T-0.8)/1.2),iz=portrait?6.4:5.0;
  camera.position.set(1.8*(1-k),2.6+(CY-2.6)*k,iz+(CZ-iz)*k);camera.lookAt(0,1.1+0.2*k,-7*k);
  if(T>=END)endIntro();
}
