let busy=false;
const kv=(l,v)=>`<div class="cr"><span class="cl">${l}</span><b class="cv">${v}</b></div>`;
function die(){
  if(state!=='play')return;state='over';
  setTimeout(()=>{if(state!=='over')return;P.coins>=2**revives?showSave():results()},650);
}
function showSave(){
  const cost=2**revives;saveT=6;phase='save';
  show('<div class="ring" id="ring"></div>'+chip()+'<h2>¡Sálvame!</h2><p>Revive con tus monedas y sigue corriendo.</p><button class="b green" onclick="revive('+cost+')">'+ic('favorite')+' Revivir '+cost+' '+TI+'</button><button class="link" onclick="results()">No, gracias</button>');
}
async function revive(c){
  if(phase!=='save'||busy)return;busy=true;
  const r=await apiAuth('/api/juego/revivir',{n:revives});
  busy=false;
  if(phase!=='save')return;
  if(!apiOk(r)){toast(apiMsg(r));return}
  await syncFrom(r);
  if(phase!=='save')return;
  revives++;hide();phase='';
  obstacles.filter(o=>o.z>-30).forEach(o=>scene.remove(o.g));obstacles=obstacles.filter(o=>o.z<=-30);
  state='play';inv=2.5;tilt=0;body.rotation.z=0;
}
async function submitRun(d,c){
  const r=await apiAuth('/api/juego/partida',{distancia:d,cubos:c});
  if(apiOk(r)){await syncFrom(r);return r}
  if(r.net)pendAdd({distancia:d,cubos:c});
  return r;
}
function resultsHtml(d,c,best,rec,gan){
  return '<div class="shead"><h2>'+(rec?'¡Nuevo récord!':'Fin de carrera')+'</h2><span class="sbal">'+TI+V(P.coins)+'</span></div>'
    +'<div>'+kv(ic('straighten')+' Distancia',d+' m')+(c>0?kv(CUBE_I+' Cubos hallados',c):'')+(gan>0?kv(TI+' Monedas ganadas','+'+gan):'')+kv(ic('emoji_events')+' Mejor distancia',best+' m')+'</div>'
    +'<div style="display:flex;gap:10px"><button class="sbuy" style="flex:1" onclick="start(true)">'+ic('replay')+' Jugar otra vez</button><button class="cbtn" style="flex:1;justify-content:center" onclick="home()">'+ic('home')+' Inicio</button></div>';
}
async function results(){
  if(phase==='done')return;phase='done';
  const d=Math.floor(dist),c=runCubes,prev=P.bestDist,mine=Math.max(prev,d);
  show(resultsHtml(d,c,mine,PROFILE&&d>prev,0),'shop sm rs');
  const r=await submitRun(d,c);
  if(!apiOk(r)||!dlg.querySelector('.rs'))return;
  const D=r.data.Datos||{},gan=+D.monedas_ganadas||0;
  if(gan>0)show(resultsHtml(d,c,P.bestDist,D.nuevo_record===true||d>prev,gan),'shop sm rs');
  else{const el=dlg.querySelector('.sbal');if(el)el.innerHTML=TI+V(P.coins)}
}
