// Foto de Timi tal como se ve en el juego (se genera con el mismo modelo 3D)
function snapTimi(){
  const key=P.own.join(',');if(snapTimi.k===key)return snapTimi.u;
  try{
    // Se usa el mismo renderizador del juego (sin crear otro contexto 3D, que en algunos teléfonos tira abajo los gráficos)
    const ex=[coop,nest,seeds,cart,board,eyesZ,...zz,...skates],sv=ex.map(o=>o.visible),lv=[legL.visible,legR.visible],bp=body.position.y,br=body.rotation.x,lr=[legL.rotation.x,legR.rotation.x];
    ex.forEach(o=>o.visible=false);legL.visible=legR.visible=true;legL.rotation.x=legR.rotation.x=0;body.position.y=0;body.rotation.x=0;
    const pc=chicken.clone(true);
    ex.forEach((o,i)=>o.visible=sv[i]);legL.visible=lv[0];legR.visible=lv[1];legL.rotation.x=lr[0];legR.rotation.x=lr[1];body.position.y=bp;body.rotation.x=br;
    pc.position.set(0,0,0);pc.rotation.set(0,Math.PI+0.55,0);pc.scale.set(1,1,1);pc.visible=true;
    const W=512,rt=new THREE.WebGLRenderTarget(W,W),sc=new THREE.Scene();
    sc.add(new THREE.HemisphereLight(0xffffff,0x6b8f3a,0.85));const dl=new THREE.DirectionalLight(0xfff0c8,0.8);dl.position.set(5,12,6);sc.add(dl);sc.add(pc);
    const cam=new THREE.PerspectiveCamera(32,1,0.1,60);cam.position.set(0.8,1.5,6.2);cam.lookAt(0,1.1,0);
    renderer.setClearColor(0x000000,0);renderer.setRenderTarget(rt);renderer.render(sc,cam);renderer.setRenderTarget(null);renderer.setClearColor(0x000000,1);
    const px=new Uint8Array(W*W*4);renderer.readRenderTargetPixels(rt,0,0,W,W,px);rt.dispose();
    const cv=document.createElement('canvas');cv.width=cv.height=W;const x=cv.getContext('2d'),id=x.createImageData(W,W);
    for(let y=0;y<W;y++)id.data.set(px.subarray((W-1-y)*W*4,(W-y)*W*4),y*W*4);
    x.putImageData(id,0,0);snapTimi.u=cv.toDataURL('image/png');snapTimi.k=key;
  }catch(e){snapTimi.u='';try{renderer.setRenderTarget(null);renderer.setClearColor(0x000000,1)}catch(_){}}
  return snapTimi.u;
}
const sid=x=>String(x).replace(/[^\w-]/g,'');
const normId=x=>String(x==null?'':(typeof x==='object'?(x.id??x.ropa_id??x.objeto_id??x.nombre??''):x)).trim().toLowerCase();
const ownsRopa=o=>P.own.some(x=>{const id=normId(x);return id===normId(o.id)||id===normId(o.nombre)||(typeof x==='object'&&(normId(x.ropa_id)===normId(o.id)||normId(x.id)===normId(o.id)));});
const equippedRopa=o=>Array.isArray(P.ropaEq)?P.ropaEq.some(x=>normId(x)===normId(o.id)||normId(x)===normId(o.nombre)):normId(P.ropaEq)===normId(o.id)||normId(P.ropaEq)===normId(o.nombre);
const invCount=id=>{
  const key=normId(id);
  const aliases={carrito:['carrito','carritos'],patineta:['patineta','patinetas'],patines:['patines','patin','patinaje']};
  let total=0;
  for(const [k,v] of Object.entries(P.inv||{})){
    const nk=normId(k);
    if(nk===key||(aliases[key]||[]).includes(nk)) total+=Number(v)||0;
  }
  return total;
};
