function shopT(t){shopTab=t;openShop(true)}
function openShop(reset){
  const sc=!reset&&dlg.classList.contains('on')&&dlg.firstChild?dlg.firstChild.scrollTop:0;
  const tabs=[['items','bolt','Objetos'],['ropa','checkroom','Ropa']];
  const head='<div class="shead"><h2>'+ic('storefront')+' Tienda</h2><span class="sbal">'+TI+V(P.coins)+'</span><button class="sx" onclick="hide()" aria-label="Cerrar">'+ic('close')+'</button></div><div class="stabs">'+tabs.map(([k,i,n])=>`<button class="stab ${shopTab===k?'on':''}" onclick="shopT('${k}')">${ic(i)} ${n}</button>`).join('')+'</div>';
  const buy=(dis,fn,txt)=>`<button class="sbuy" ${dis?'disabled':''} onclick="${fn}">${txt}</button>`;
  const card=(img,name,desc,tag,btn)=>`<div class="sc"><div class="sp">${img}</div><span class="stag">${tag}</span><h3>${esc(name)}</h3><p>${esc(desc)}</p>${btn}</div>`;
  const none=k=>!CAT_OK?'':CAT[k].length?null:'<p class="shint" style="padding:18px 0;text-align:center">No hay artículos disponibles.</p>';
  const hab=p=>p.habilidad?`<span class="stag">${esc(p.habilidad)}</span>`:'';
  let body;
  if(shopTab==='items')body=none('objetos')??('<div class="sgrid">'+CAT.objetos.map(o=>card(itemImg(o),o.nombre,o.descripcion||'',(!PROFILE?'N/A':P.inv[o.id]>0?'Tienes ×'+P.inv[o.id]:'Nuevo'),buy(!PROFILE||P.coins<o.precio,`shopBuy('${sid(o.id)}')`,o.precio+' '+TI))).join('')+'</div>');
  else if(shopTab==='ropa')body=none('ropa')??('<div class="sgrid">'+CAT.ropa.map(i=>{const own=P.own.includes(i.id);return card(itemImg(i),i.nombre,i.descripcion||'',!PROFILE?'N/A':own?'Comprado':'Nuevo',own?'<button class="sbuy" disabled>'+ic('check')+' Tuyo</button>':buy(!PROFILE||P.coins<i.precio,`shopBuy('${sid(i.id)}')`,i.precio+' '+TI))}).join('')+'</div>');
  else body='<p class="shint" style="padding:18px 0;text-align:center">No hay artículos disponibles.</p>';
  curPanel='shop';show(head+offBanner()+body,'shop');
  dlg.firstChild.scrollTop=sc;
}
function shopBuy(id){guard(async()=>{
  const r=await apiAuth('/api/tienda/comprar',{id});
  if(!apiOk(r)){toast(apiMsg(r));return}
  await syncFrom(r);toast('¡Compra realizada!');openShop();
})}
function meT(t){meTab=t;openMe(true)}
function mePj(d){const n=P.pj.length;meIdx=(meIdx+d+n)%n;openMe()}
function meT(t){meTab=t;openMe(true)}
async function openMe(reset){
  // Recargar perfil e inventario desde el servidor cada vez que se abre.
  // Si la petición falla, se conserva la última información válida en memoria.
  await Promise.all([refreshProfile(), loadCatalog()]);
  renderMe(reset);
}
function renderMe(reset){
  const sc=!reset&&dlg.classList.contains('on')&&dlg.firstChild?dlg.firstChild.scrollTop:0;
  const head='<div class="shead"><h2>'+ic('inventory_2')+' Inventario</h2><span class="sbal">'+TI+V(P.coins)+'</span><button class="sx" onclick="hide()" aria-label="Cerrar">'+ic('close')+'</button></div>';
  const card=(img,name,desc,tag,btn)=>`<div class="sc"><div class="sp">${img}</div>${tag?`<span class="stag">${tag}</span>`:""}<h3>${esc(name)}</h3>${btn}</div>`;
  const tabs='<div class="inv-tabs"><button class="'+(meTab==='obj'?'on':'')+'" onclick="meT(\'obj\')">Objetos</button>'+
    ((P.own.length>0||CAT.ropa.some(o=>ownsRopa(o)))?'<button class="'+(meTab==='ropa'?'on':'')+'" onclick="meT(\'ropa\')">Ropa</button>':'')+'</div>';
  let body='<div class="sgrid">';
  if(meTab==='ropa'){
    const owned=CAT.ropa.filter(o=>ownsRopa(o));
    if(owned.length){
      body+=owned.map(o=>{
        const equipped=equippedRopa(o);
        return card(itemImg(o),o.nombre,o.descripcion||'',equipped?'Equipado':'',
          '<button class="sbuy" onclick="toggleRopa(\''+sid(o.id)+'\','+(equipped?'false':'true')+')">'+(equipped?'Quitar':'Equipar')+'</button>');
      }).join('');
    }else{
      body+=P.own.map(x=>{
        const id=normId(x),o=CAT.ropa.find(y=>normId(y.id)===id||normId(y.nombre)===id);
        const label=o?(o.nombre||String(x)):(typeof x==='object'?(x.nombre||x.id||'Ropa'):String(x));
        const itemId=o?o.id:(typeof x==='object'?(x.id||x.ropa_id||x.objeto_id):x);
        const equipped=o?equippedRopa(o):equippedRopa({id:itemId,nombre:label});
        return card(o?itemImg(o):(IMG[id]||PH),label,o?(o.descripcion||''):'',equipped?'Equipado':'',
          '<button class="sbuy" onclick="toggleRopa(\''+sid(itemId)+'\','+(equipped?'false':'true')+')">'+(equipped?'Quitar':'Equipar')+'</button>');
      }).join('');
    }
    if(!P.own.length&&!owned.length)body+='<p class="shint" style="grid-column:1/-1;text-align:center">No tienes ropa todavía.</p>';
  }else{
    if(P.cubos>0)body+=card(CUBE_BIG,'Cubo','Contiene un objeto al azar. ¡Ábrelo para descubrirlo!','Tienes ×'+V(P.cubos),`<button class="sbuy" ${!PROFILE?'disabled':''} onclick="abrirCubo()">Abrir</button>`);
    // Mostrar únicamente los potenciadores que el jugador realmente posee.
    const powerups=Object.keys(PU).filter(id=>invCount(id)>0).map(id=>{
      const n=invCount(id);
      const catalogItem=CAT.objetos.find(o=>normId(o.id)===id||normId(o.nombre)===normId(PU[id].n));
      const img=catalogItem?itemImg(catalogItem):(IMG[id]||PH);
      return card(img,PU[id].n,PU[id].d,'Tienes ×'+V(n),'');
    });
    body+=powerups.join('');
    const powerupIds=new Set(Object.keys(PU));
    body+=CAT.objetos.filter(o=>!powerupIds.has(normId(o.id))&&invCount(o.id)>0).map(o=>{
      const n=invCount(o.id);
      return card(itemImg(o),o.nombre,o.descripcion||'','Tienes ×'+V(n),'');
    }).join('');
    if(!P.cubos&&!Object.keys(PU).some(id=>invCount(id)>0)&&!CAT.objetos.some(o=>!powerupIds.has(normId(o.id))&&invCount(o.id)>0))body+='<p class="shint" style="grid-column:1/-1;padding:8px 0;text-align:center">No tienes objetos todavía; aquí aparecerán tus cantidades.</p>';
  }
  body+='</div>';
  curPanel='me';show(head+tabs+offBanner()+body,'shop');
  if(dlg.firstChild)dlg.firstChild.scrollTop=sc;
}
async function toggleRopa(id,equipar){
  if(busy)return;busy=true;
  try{
    const path=equipar?'/api/ropa/equipar':'/api/ropa/desequipar';
    const r=await apiAuth(path,{id});
    if(!apiOk(r)){toast(apiMsg(r));return}
    await syncFrom(r);
    toast(equipar?'Ropa equipada':'Ropa desequipada');
    openMe(true);
  }finally{busy=false}
}
function equipPj(id){guard(async()=>{
  const r=await apiAuth('/api/personajes/equipar',{id});
  if(!apiOk(r)){toast(apiMsg(r));return}
  await syncFrom(r);openMe();
})}
async function abrirCubo(){
  if(busy||P.cubos<1)return;busy=true;
  show('<img class="cbi shake" src="'+CUBE_FULL+'" alt=""><h3>Abriendo cubo…</h3>','cube');
  const t0=Date.now(),r=await apiAuth('/api/cubos/abrir');
  await new Promise(x=>setTimeout(x,Math.max(0,1500-(Date.now()-t0))));
  busy=false;
  if(!apiOk(r)){toast(apiMsg(r));openMe(true);return}
  const D=r.data.Datos||{},id=sid(String(D.objeto||D.id||'').toLowerCase()),nm=D.nombre||nameOf(id)||D.objeto||'Objeto misterioso',n=+D.cantidad||1;
  await refreshProfile();
  show('<div class="gift">'+cubeImg(D,id,nm)+'</div><p class="got">¡Obtuviste!</p><h3>'+esc(nm)+(n>1?' ×'+n:'')+'</h3><button class="sbuy" style="width:100%" onclick="meTab=\'obj\';openMe(true)">Aceptar</button>','cube');
}

